  og_image = '/assets/images/cameraman-operating-equipment-in-studio-T3LZ2B2.jpg',
  og_image_alt = 'Cameraman operating equipment in a television commercial studio',
  image_alt = 'Cameraman operating equipment in a television commercial studio',
  robots = 'index,follow',
  focus_keyword = 'TVC format',
