  faq = '[{"a":"A TVC format defines the duration, structure, scripting, production, and delivery requirements of a television commercial.","q":"What is a TVC format?"},{"a":"TVC stands for Television Commercial, a short advertising film created to promote a brand, product, or service.","q":"What does TVC stand for?"},{"a":"Common durations include 10, 15, 20, 30, and 60 seconds, depending on the campaign and media requirement.","q":"What are common TVC durations?"},{"a":"The ideal length depends on the message. Short spots suit simple ideas, while 30- or 60-second versions allow more storytelling.","q":"How long should a TV commercial be?"},{"a":"A TVC script describes both visuals and audio, including scenes, dialogue, voiceover, music, and sound effects.","q":"What is a TVC script?"},{"a":"The process typically includes concept development, scripting, pre-production, filming, post-production, and final delivery.","q":"What are the main stages of TVC production?"},{"a":"Yes. A TV commercial can be adapted into shorter, vertical, or platform-specific versions for digital channels.","q":"Can a TVC be used on social media?"},{"a":"A strong TVC combines a clear idea, engaging storytelling, memorable visuals, and a message that connects naturally with the audience.","q":"What makes a TVC effective?"},{"a":"Costs depend on the concept, cast, locations, crew, equipment, shooting schedule, and post-production requirements.","q":"How much does TVC production cost?"},{"a":"Review its portfolio, creative approach, production capabilities, communication process, and experience with campaigns similar to yours.","q":"How do I choose a TVC production company?"}]'::jsonb,
  tldr = 'The TVC format covers how a television commercial is structured: its duration, script, visuals and audio, production stages, and delivery specs. Typical spots run 10, 15, 20, 30, or 60 seconds, and the right length should be driven by the message rather than convention.',
  published_at = '2026-08-19T00:00:00+00:00'
where slug = 'tvc-format-guide';
